 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h - 2):
        for c in range(w - 2):
            if grid[r+1][c+1] != 2:
                continue
            if any(grid[rr][cc] != 3 for rr in range(r, r+3) for cc in range(c, c+3) if (rr, cc) != (r+1, c+1)):
                continue
            cr, cc = r+1, c+1
            # The marker sits on one of a series of parallel 2-lines.
            row_score = sum(v == 2 for v in grid[cr])
            col_score = sum(grid[rr][cc] == 2 for rr in range(h))
            horizontal_line = row_score >= col_score
            if horizontal_line:
                candidates = [rr for rr in range(cr+1, h) if sum(v == 2 for v in grid[rr]) >= max(3, w * 0.6)]
                if not candidates:
                    continue
                tr, tc = min(candidates)
                # Transposed motif: a long horizontal stem and a 3x3 central block.
                for dc in range(-3, 4):
                    if 0 <= tc+dc < w and grid[tr][tc+dc] == 0:
                        out[tr][tc+dc] = 1
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        rr, c2 = tr+dr, tc+dc
                        if 0 <= rr < h and 0 <= c2 < w and (rr, c2) != (tr, tc) and grid[rr][c2] == 0:
                            out[rr][c2] = 1
            else:
                candidates = [c2 for c2 in range(cc+1, w) if sum(grid[rr][c2] == 2 for rr in range(h)) >= max(3, h * 0.6)]
                if not candidates:
                    continue
                tr, tc = cr, min(candidates)
                for dc in range(-3, 4):
                    c2 = tc+dc
                    if 0 <= c2 < w and grid[tr][c2] == 0:
                        out[tr][c2] = 1
                for dr in range(-1, 2):
                    for dc in range(-1, 2):
                        rr, c2 = tr+dr, tc+dc
                        if 0 <= rr < h and 0 <= c2 < w and (rr, c2) != (tr, tc) and grid[rr][c2] == 0:
                            out[rr][c2] = 1
    return out

